Em modo de desenvolvimento (`npm run dev`), o componente abaixo renderiza uma lista com `map` **sem** a prop `key`. O que o React faz?

```jsx
function Lista({ itens }) {
  return (
    <ul>
      {itens.map((item) => (
        <li>{item.nome}</li>
      ))}
    </ul>
  );
}
```

params.code:
import { renderToStaticMarkup } from 'react-dom/server';
import { Children } from 'react';
const avisos = [];
console.error = (...a) => avisos.push(a.join(' '));
function Lista({ itens }) {
  return (
    <ul>
      {itens.map((item) => (
        <li>{item.nome}</li>
      ))}
    </ul>
  );
}
const html = renderToStaticMarkup(<Lista itens={[{ nome: 'A' }, { nome: 'B' }]} />);
console.log(html.includes('<li>A</li><li>B</li>') && avisos.some((a) => a.includes('unique "key"')) ? 'renderiza e avisa' : 'outro: ' + html + avisos.length);

