stem:
Em modo de desenvolvimento (`npm run dev`), a lista abaixo é montada no navegador. Dois itens usam a mesma `key`:

```jsx
const itens = [{ id: 1, nome: "A" }, { id: 1, nome: "B" }];
createRoot(document.getElementById("root")).render(
  <ul>
    {itens.map((i) => <li key={i.id}>{i.nome}</li>)}
  </ul>
);
```
O que o React faz?

params.code:
import { JSDOM } from 'jsdom';
const dom = new JSDOM('<!doctype html><div id="root"></div>');
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.IS_REACT_ACT_ENVIRONMENT = true;
const avisos = [];
console.error = (...a) => avisos.push(a.join(' '));
const React = (await import('react')).default;
const { createRoot } = await import('react-dom/client');
const itens = [{ id: 1, nome: 'A' }, { id: 1, nome: 'B' }];
const root = createRoot(document.getElementById('root'));
await React.act(async () => { root.render(<ul>{itens.map((i) => <li key={i.id}>{i.nome}</li>)}</ul>); });
const html = document.getElementById('root').innerHTML;
console.log(html.includes('<li>A</li><li>B</li>') && avisos.some((a) => a.includes('same key')) ? 'renderiza e avisa' : 'outro: ' + html + avisos.length);

